// Klaviyo on a private API key: every operation of Klaviyo's API (actions.json, generated by
// `bun scripts/openapi-actions.ts klaviyo`). Automations start by polling (polls/klaviyo.ts): Klaviyo's webhooks need a
// paid add-on, while its events list works on every plan.
import type { OwnApp } from "../index";
import { type Api, call, specActions } from "../openapi";

// the API version every call asks for; move it with the spec when regenerating
export const REVISION = "2026-10-15";

export const api: Api = {
  name: "Klaviyo",
  base: "https://a.klaviyo.com",
  tokenHelp: "Klaviyo → Settings → Account → API keys → Create Private API Key",
  // the /client/ calls (the ones taking company_id) are for a site's visitors: the public key only, no private key
  auth: (key, input) => ({ ...(input.company_id === undefined && { Authorization: `Klaviyo-API-Key ${key}` }), revision: REVISION }),
};

export const klaviyo: OwnApp = {
  app: "klaviyo",
  name: "Klaviyo",
  logo: "/logos/klaviyo.svg",
  keyField: {
    label: "Private API key",
    help: "In Klaviyo, open Settings → Account → API keys and click Create Private API Key. Name it Emplio, choose Full Access Key (or Custom Key with read and write on everything Emplio should handle), create it and copy the key, which starts with pk_. Only account owners, admins and managers can make one.",
    placeholder: "pk_...",
  },
  async check(key) {
    const { data } = (await call(api, key, { method: "GET", path: "/api/accounts", query: [], headers: [] }, {})) as {
      data?: { id: string; attributes?: { contact_information?: { organization_name?: string; default_sender_email?: string } } }[];
    };
    const info = data?.[0]?.attributes?.contact_information;
    return info?.organization_name || info?.default_sender_email || "Klaviyo";
  },
  actions: await specActions(new URL("./actions.json", import.meta.url), api),
};
